<script setup lang="ts">
import LoadingValue from './components/LoadingValue.vue';
import TableLoadingRows from './components/TableLoadingRows.vue';
import TableUpdating from './components/TableUpdating.vue';
import {computed,inject,onBeforeUnmount,ref,useId,watch} from 'vue';
import {adminSessionKey} from './adminSession';
import {units4,decimal4} from './portalAmounts';
import {paymentAdminOrdersGetApiV1AdminPaymentsOrders as readOrders,userDirectoryDetailGetApiV1AdminUsersIdDirectoryDetail as readUser} from './api';
import PaymentOrderDrawer from './PaymentOrderDrawer.vue';
import PromoterIcon from './PromoterIcon.vue';
import './finance.css';
type Record=NonNullable<Awaited<ReturnType<typeof readOrders>>['data']['items']>[number];
type User=NonNullable<Awaited<ReturnType<typeof readUser>>['data']['user']>;
const statGradientId=useId();
const props=withDefaults(defineProps<{review?:boolean}>(),{review:false});
const session=inject(adminSessionKey),allowed=computed(()=>['ADMIN','NORMAL_ADMIN'].includes(session?.currentAdmin.value?.role||''));
const loaded=ref(false);
const records=ref<Record[]>([]),users=ref<{[id:string]:User}>({}),busy=ref(false),error=ref(''),selected=ref<Record|null>(null),checked=ref<string[]>([]);
const day=(value?:string|null)=>value?new Date(Date.parse(value)+28800000).toISOString().slice(0,10):'';
const today=()=>day(new Date().toISOString()),shift=(date:string,n:number)=>new Date(Date.parse(date+'T00:00:00Z')+n*86400000).toISOString().slice(0,10);
const search=ref(''),method=ref(''),status=ref(''),account=ref(''),source=ref(''),kind=ref(''),period=ref('7'),from=ref(shift(today(),-6)),to=ref(today()),only=ref(false),tab=ref('');
const applied=ref({search:'',method:'',status:'',account:'',source:'',kind:'',from:from.value,to:to.value,only:false});
const size=ref(10),page=ref(1),jump=ref(1);
const names:{[name:string]:string}={PERSONAL:'个人',ENTERPRISE:'企业',API:'API'};
const labels:{[name:string]:string}={PAID:'已支付',REVIEW_PENDING:'待审核',PENDING:'待支付',REFUND_PENDING:'退款处理中',REFUNDED:'已退款',REJECTED:'已驳回',EXPIRED:'已过期'};
const kinds=[['','全部'],['MANUAL','人工增加'],['DEBIT','人工减少'],['REFUND_ADJUST','退款调整'],['GIFT','活动赠送']];
const sources:{[name:string]:string}={NATURAL:'自然注册',REFERRAL:'代理推荐',ADMIN:'管理员添加'};
const user=(r:Record)=>users.value[r.order?.userId||''];
const category=(r:Record)=>r.order?.source==='MANUAL'?'MANUAL':'';
const methodName=(r:Record)=>r.order?.source==='CORPORATE'?'对公转账':r.order?.source==='MANUAL'?'人工充值':r.order?.paymentMethod==='WECHAT'?'微信支付':r.order?.paymentMethod==='ALIPAY'?'支付宝':'线上支付';
const state=(r:Record)=>props.review?(r.order?.status==='PAID'?(r.order.fulfilled?'已通过':'入账中'):labels[r.order?.status||'']||'—'):r.order?.status==='PAID'&&!r.order.fulfilled?'入账中':labels[r.order?.status||'']||'—';
const cash=(v?:string|null)=>{if(units4(v)===null)return '—';const[w,f='']=v!.split('.');return w!.replace(/\B(?=(\d{3})+(?!\d))/g,',')+'.'+f.padEnd(2,'0').slice(0,2);};
const time=(v?:string|null)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—';
const sum=(rows:Record[])=>{let n=0n;for(const r of rows){const v=units4(r.order?.amount4);if(v===null)return null;n+=v;}return decimal4(n);};
const scope=computed(()=>records.value.filter(r=>!props.review||r.order?.source==='MANUAL'));
const filtered=computed(()=>scope.value.filter(r=>{const o=r.order!,q=applied.value,u=user(r),date=day(o.createdAt);const hay=[o.orderId,u?.nickname,u?.phone,o.userId,o.submittedBy,r.transactionId].join(' ').toLowerCase();return (!q.search||hay.includes(q.search.toLowerCase()))&&(!q.method||(['MANUAL','CORPORATE'].includes(q.method)?o.source===q.method:o.paymentMethod===q.method))&&(!q.status||o.status===q.status)&&(!q.account||o.accountType===q.account)&&(!q.source||u?.source===q.source)&&(!q.kind||category(r)===q.kind)&&(!q.from||date>=q.from)&&(!q.to||date<=q.to)&&(!q.only||(props.review?o.status==='REVIEW_PENDING':['REFUND_PENDING','EXPIRED','REJECTED'].includes(o.status||'')||o.status==='PAID'&&!o.fulfilled));}));
const rows=computed(()=>filtered.value.filter(r=>!props.review||!tab.value||category(r)===tab.value));
const pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/size.value))),visible=computed(()=>rows.value.slice((page.value-1)*size.value,page.value*size.value));
const pageNumbers=computed(()=>[...new Set([1,page.value-1,page.value,page.value+1,pages.value])].filter(n=>n>0&&n<=pages.value).sort((a,b)=>a-b));
const allSelected=computed(()=>!!visible.value.length&&visible.value.every(r=>checked.value.includes(r.order!.orderId!)));
const pending=computed(()=>scope.value.filter(r=>r.order?.status==='REVIEW_PENDING'));
const paidToday=computed(()=>records.value.filter(r=>day(r.paidAt)===today())),paidYesterday=computed(()=>records.value.filter(r=>day(r.paidAt)===shift(today(),-1)));
const approvedToday=computed(()=>scope.value.filter(r=>day(r.paidAt)===today()));
const rejectedToday=computed(()=>scope.value.filter(r=>day(r.order?.rejectedAt)===today()).length);
const thisMonth=computed(()=>scope.value.filter(r=>day(r.order?.createdAt).startsWith(today().slice(0,7))).length);
const refunded=computed(()=>records.value.filter(r=>r.order?.status==='REFUNDED'));
const refundHistoryComplete=computed(()=>refunded.value.every(r=>!!r.refundedAt&&Number.isFinite(Date.parse(r.refundedAt))));
const refundAmount=(date:string)=>refundHistoryComplete.value?sum(refunded.value.filter(r=>day(r.refundedAt)===date)):null;
const successful=computed(()=>rows.value.filter(r=>r.paidAt).length);
const successRate=computed(()=>rows.value.length?(successful.value*100/rows.value.length).toFixed(1)+'%':'—');
function delta(a:string|null,b:string|null){const x=units4(a),y=units4(b);if(x===null||y===null||y===0n)return '—';const n=(x-y)*10000n/y;return `${n>=0?'+':'−'}${Number(n<0?-n:n)/100}%`;}
const trend=(field:'amount'|'count'|'refund')=>{const values=Array.from({length:7},(_,i)=>{const rs=(field==='refund'?refunded.value:records.value).filter(r=>day(field==='refund'?r.refundedAt:r.paidAt)===shift(today(),i-6));return field==='count'?BigInt(rs.length):units4(sum(rs))||0n;});const max=values.reduce((a,b)=>a>b?a:b,1n);return values.map((n,i)=>`${i*15},${48-Number(n*3800n/max)/100}`).join(' ');};
let version=0;
async function load(){if(!allowed.value)return;const own=++version;busy.value=true;error.value='';const cutoff=new Date().toISOString();try{const all:Record[]=[];
 // ponytail: full snapshot supports local cross-field filtering; move filters to the server if order volume makes this expensive.
 for(let offset=0;;offset+=100){const result=(await readOrders({offset,limit:100,to:cutoff})).data;if(own!==version)return;if(!Array.isArray(result.items)||!Number.isSafeInteger(result.total)||result.total<0||(!result.items.length&&offset<result.total))throw Error('invalid page');for(const r of result.items){if(!r.order?.orderId||!r.order.userId)throw Error('invalid order');all.push(r);}if(offset+result.items.length>=result.total)break;}
 const ids=[...new Set(all.map(r=>r.order!.userId!))];const values=await Promise.allSettled(ids.map(id=>readUser(id)));if(own!==version)return;users.value=Object.fromEntries(values.flatMap((v,i)=>v.status==='fulfilled'&&v.value.data.user?.id===ids[i]?[[ids[i]!,v.value.data.user]]:[]));records.value=all;loaded.value=true;checked.value=[];page.value=Math.min(page.value,pages.value);
 if(selected.value)selected.value=all.find(r=>r.order!.orderId===selected.value?.order?.orderId)||null;
 }catch{if(own===version)error.value='订单读取失败，请重试。';}finally{if(own===version)busy.value=false;}}
function apply(){if(from.value&&to.value&&from.value>to.value){error.value='开始日期不能晚于结束日期。';return;}error.value='';applied.value={search:search.value.trim(),method:method.value,status:status.value,account:account.value,source:source.value,kind:kind.value,from:from.value,to:to.value,only:only.value};page.value=1;checked.value=[];}
function quick(value:string){period.value=value;if(value==='custom')return;from.value=value==='today'?today():value==='yesterday'?shift(today(),-1):shift(today(),value==='7'?-6:-29);to.value=value==='yesterday'?from.value:today();apply();}
function reset(){search.value=method.value=status.value=account.value=source.value=kind.value=tab.value='';only.value=false;quick('7');}
function chooseTab(value:string){tab.value=value;page.value=1;checked.value=[];}
function selectAll(){checked.value=allSelected.value?[]:visible.value.map(r=>r.order!.orderId!);}
function go(n:number){page.value=Math.min(pages.value,Math.max(1,Math.trunc(n)||1));jump.value=page.value;checked.value=[];}
function exportCsv(){const output=rows.value.filter(r=>!checked.value.length||checked.value.includes(r.order!.orderId!));const cell=(v:unknown)=>{let s=String(v??'');if(/^\s*[=+\-@]/.test(s)||/^[\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const lines=[['订单号','用户','手机号','账户类型','金额（元）','来源','支付方式','状态','申请时间','支付时间'],...output.map(r=>[r.order!.orderId,user(r)?.nickname,user(r)?.phone,names[r.order!.accountType||''],r.order!.amount4,r.order!.source==='CORPORATE'?'对公转账':category(r)?kinds.find(k=>k[0]===category(r))?.[1]:'线上支付',methodName(r),state(r),r.order!.createdAt,r.paidAt])];const url=URL.createObjectURL(new Blob(['\ufeff'+lines.map(l=>l.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=props.review?'资金审核.csv':'支付订单.csv';a.click();URL.revokeObjectURL(url);}
watch(()=>[session?.currentAdmin.value?.username,session?.currentAdmin.value?.userId,session?.currentAdmin.value?.role,props.review],()=>{version++;loaded.value=false;records.value=[];users.value={};selected.value=null;checked.value=[];if(allowed.value)void load();},{immediate:true});
onBeforeUnmount(()=>{version++;});
</script>
<template><section class="finance-page"><template v-if="allowed"><div class="finance-breadcrumb"><PromoterIcon name="home"/>运营管理 <span>›</span><strong>{{review?'资金审核':'支付订单'}}</strong></div><header class="finance-heading"><h1>{{review?'资金审核':'支付订单'}}</h1><p>{{review?'管理资金申请，核对到账信息与审核状态。':'管理所有充值订单，实时掌握支付状态与到账情况。'}}</p></header>
<div v-if="review" class="finance-stats review-stats">
  <article class="review-stat-card">
    <span class="finance-stat-icon violet"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="10" fill="white"/><path d="M12 6v6l4 2" fill="none" stroke="#8a84ff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></span>
    <div><span>待审核</span><strong><LoadingValue :loading="busy&&!loaded">{{pending.length}} <small>条</small></LoadingValue></strong><p>待审核金额 <b><LoadingValue :loading="busy&&!loaded">¥ {{cash(sum(pending))}}</LoadingValue></b></p></div>
  </article>
  <article class="review-stat-card">
    <span class="finance-stat-icon green"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="10" fill="white"/><path d="m7.5 12 3 3 6-6" fill="none" stroke="#15c7a4" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></span>
    <div><span>今日已通过</span><strong><LoadingValue :loading="busy&&!loaded">{{approvedToday.length}} <small>条</small></LoadingValue></strong><p>金额 <b><LoadingValue :loading="busy&&!loaded">¥ {{cash(sum(approvedToday))}}</LoadingValue></b></p></div>
    <svg class="review-stat-art" viewBox="0 0 120 112" aria-hidden="true" fill="none"><defs><linearGradient :id="`${statGradientId}-review`" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#aebaff"/><stop offset="1" stop-color="#6878f5"/></linearGradient></defs><circle cx="79" cy="43" r="40" fill="#eff4ff"/><circle cx="48" cy="70" r="40" fill="#eaf1ff"/><rect x="51" y="14" width="49" height="55" rx="8" fill="#dce6ff" opacity=".65"/><rect x="60" y="24" width="33" height="35" rx="5" :fill="`url(#${statGradientId}-review)`"/><rect x="65" y="32" width="32" height="29" rx="5" :fill="`url(#${statGradientId}-review)`"/><path d="M69 40h20M69 48h20" stroke="white" stroke-width="3" stroke-linecap="round" opacity=".9"/><path d="m34 88 9-9V65m0 8 5-4" stroke="#c8d7fa" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="34" cy="88" r="6" fill="#c8d7fa"/></svg>
  </article>
  <article class="finance-review-counts"><span>今日已驳回 <b><LoadingValue :loading="busy&&!loaded">{{rejectedToday}} 条</LoadingValue></b></span><span>本月累计 <strong><LoadingValue :loading="busy&&!loaded">{{thisMonth}} 条</LoadingValue></strong></span></article>
</div>
<div v-else class="finance-stats payment-stats">
  <article>
    <span class="finance-stat-icon violet"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"><path d="M12 2v8M5 10V8a7 4 0 0 1 14 0v2"/><path d="M4 10h16v5a8 7 0 0 1-16 0Z" fill="currentColor" stroke="none"/></svg></span>
    <div><span>今日支付金额</span><strong><LoadingValue :loading="busy&&!loaded">¥ {{cash(sum(paidToday))}}</LoadingValue></strong><p>较昨日 <b><LoadingValue :loading="busy&&!loaded">{{delta(sum(paidToday),sum(paidYesterday))}}</LoadingValue></b></p></div>
    <svg class="payment-stat-trend" viewBox="0 0 90 50" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient :id="`${statGradientId}-amount`" x1="0" y1="0" x2="0" y2="1"><stop stop-color="currentColor" stop-opacity=".26"/><stop offset="1" stop-color="currentColor" stop-opacity="0"/></linearGradient></defs><polygon :points="`0,50 ${trend('amount')} 90,50`" :fill="`url(#${statGradientId}-amount)`"/><polyline :points="trend('amount')"/></svg>
  </article>
  <article>
    <span class="finance-stat-icon green"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2"/><path d="M7 8h2m4 0h4M7 13h2m4 0h2"/><path d="m15 16 2 2 3-4"/></svg></span>
    <div><span>今日成功订单</span><strong><LoadingValue :loading="busy&&!loaded">{{paidToday.length}} <small>单</small></LoadingValue></strong><p>较昨日 <b><LoadingValue :loading="busy&&!loaded">{{delta(decimal4(BigInt(paidToday.length)),decimal4(BigInt(paidYesterday.length)))}}</LoadingValue></b></p></div>
    <svg class="payment-stat-trend" viewBox="0 0 90 50" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient :id="`${statGradientId}-count`" x1="0" y1="0" x2="0" y2="1"><stop stop-color="currentColor" stop-opacity=".3"/><stop offset="1" stop-color="currentColor" stop-opacity="0"/></linearGradient></defs><polygon :points="`0,50 ${trend('count')} 90,50`" :fill="`url(#${statGradientId}-count)`"/><polyline :points="trend('count')"/></svg>
  </article>
  <article>
    <span class="finance-stat-icon pink"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M7 4a9 9 0 0 0 0 16M17 4a9 9 0 0 1 0 16M12 2v4m0 12v4M4 12h16m-3-3 3 3-3 3m-10-6-3 3 3 3"/></svg></span>
    <div><span>退款金额</span><strong><LoadingValue :loading="busy&&!loaded">¥ {{cash(refundAmount(today()))}}</LoadingValue></strong><p>较昨日 <b><LoadingValue :loading="busy&&!loaded">{{delta(refundAmount(today()),refundAmount(shift(today(),-1)))}}</LoadingValue></b></p></div>
    <svg v-if="refundHistoryComplete" class="payment-stat-trend" viewBox="0 0 90 50" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient :id="`${statGradientId}-refund`" x1="0" y1="0" x2="0" y2="1"><stop stop-color="currentColor" stop-opacity=".26"/><stop offset="1" stop-color="currentColor" stop-opacity="0"/></linearGradient></defs><polygon :points="`0,50 ${trend('refund')} 90,50`" :fill="`url(#${statGradientId}-refund)`"/><polyline :points="trend('refund')"/></svg>
  </article>
</div>
<form class="finance-filters" @submit.prevent="apply"><div class="finance-filter-row"><label class="finance-search"><span class="sr-only">搜索订单</span><input v-model="search" aria-label="搜索订单" :placeholder="review?'搜索用户 / 手机号 / 申请人 / 流水号':'订单号 / 用户名 / 手机号'"/><PromoterIcon name="search"/></label><select v-if="review" v-model="kind" aria-label="申请类型"><option value="">申请类型</option><option v-for="k in kinds.slice(1)" :key="k[0]" :value="k[0]">{{k[1]}}</option></select><select v-else v-model="method" aria-label="支付方式"><option value="">支付方式</option><option value="WECHAT">微信支付</option><option value="ALIPAY">支付宝</option><option value="MANUAL">人工充值</option><option value="CORPORATE">对公转账</option></select><select v-model="account" aria-label="账户类型"><option value="">账户类型</option><option v-for="(label,value) in names" :key="value" :value="value">{{label}}</option></select><select v-if="review" v-model="source" aria-label="用户来源"><option value="">用户来源</option><option v-for="(label,value) in sources" :key="value" :value="value">{{label}}</option></select><select v-model="status" aria-label="订单状态"><option value="">{{review?'审核状态':'订单状态'}}</option><option v-for="(label,value) in labels" :key="value" :value="value">{{value==='PAID'&&review?'已通过':label}}</option></select><div class="finance-dates"><input v-model="from" type="date" aria-label="开始日期" @change="period='custom'"/><span>→</span><input v-model="to" type="date" aria-label="结束日期" @change="period='custom'"/></div></div><div class="finance-filter-row"><div class="finance-presets"><button v-for="entry in [['today','今天'],['yesterday','昨天'],['7','近7天'],['30','近30天'],['custom','自定义']]" :key="entry[0]" type="button" :aria-pressed="period===entry[0]" @click="quick(entry[0]!)">{{entry[1]}}</button></div><label class="finance-only"><input v-model="only" type="checkbox"/>{{review?'仅看待审核':'仅看异常'}}</label><div class="finance-filter-actions"><button type="submit" class="finance-primary" :disabled="busy">查询</button><button type="button" @click="reset">重置</button><button type="button" class="finance-icon-button" aria-label="刷新订单" :disabled="busy" @click="load">↻</button></div></div></form>
<p v-if="error" class="finance-error" role="alert">{{error}} <button type="button" @click="load">重试</button></p>
<section class="finance-list"><header><nav v-if="review" class="finance-categories" aria-label="资金申请分类"><button v-for="k in kinds" :key="k[0]" type="button" :class="`kind-${k[0]}`" :aria-pressed="tab===k[0]" @click="chooseTab(k[0]!)">{{k[1]}}（{{filtered.filter(r=>!k[0]||category(r)===k[0]).length}}）</button></nav><h2 v-else>订单列表（共 {{loaded?rows.length:'—'}} 条）</h2><div class="finance-list-actions"><span v-if="!review">成功率 <strong>{{successRate}}</strong></span><button type="button" :disabled="busy||!rows.length" @click="exportCsv"><PromoterIcon name="download"/>{{review?(checked.length?'导出所选':'导出'):'导出订单'}}</button></div></header>
<div class="finance-table data-table-region" role="region" tabindex="0" aria-label="订单表格，可横向滚动" :aria-busy="busy"><TableUpdating v-if="busy&&visible.length"/><table><thead><tr><th v-if="review"><input type="checkbox" aria-label="选择本页所有申请" :checked="allSelected" @change="selectAll"/></th><th>{{review?'申请时间 ↓':'订单号'}}</th><th>用户</th><th v-if="review">手机号</th><th>账户类型</th><th v-if="review">用户来源</th><th>{{review?'申请类型':'订单金额'}}</th><th>{{review?'申请金额':'实付金额'}}</th><th>{{review?'申请人':'支付方式'}}</th><th>状态</th><th v-if="!review">支付时间</th><th>操作</th></tr></thead><tbody><TableLoadingRows v-if="busy&&!visible.length" :columns="review?11:9" label="正在读取订单…"/><tr v-for="r in visible" :key="r.order!.orderId!" :class="{'is-selected':selected?.order?.orderId===r.order!.orderId}"><td v-if="review"><input v-model="checked" type="checkbox" :value="r.order!.orderId" :aria-label="'选择申请 '+r.order!.orderId"/></td><td :title="r.order!.orderId||undefined">{{review?time(r.order!.createdAt):r.order!.orderId}}<small v-if="review" class="finance-order-id">{{r.order!.orderId}}</small></td><td>{{user(r)?.nickname||'—'}}</td><td v-if="review">{{user(r)?.phone||'—'}}</td><td><span class="finance-pill neutral">{{names[r.order!.accountType||'']||'—'}}</span></td><td v-if="review"><span class="finance-pill source">{{sources[user(r)?.source||'']||'—'}}</span></td><td :title="r.order!.amount4||undefined"><span v-if="review" class="finance-pill" :class="category(r)==='MANUAL'?'green':'blue'">{{kinds.find(k=>k[0]===category(r))?.[1]}}</span><template v-else>¥ {{cash(r.order!.amount4)}}</template></td><td :title="r.order!.amount4||undefined">{{review||r.paidAt?'¥ '+cash(r.order!.amount4):'—'}}</td><td><template v-if="review">{{r.order!.submittedBy||'—'}}</template><span v-else class="finance-pill payment-method-pill" :class="!category(r)&&r.order!.paymentMethod==='WECHAT'?'green':'blue'">
<svg v-if="r.order?.source==='CORPORATE'" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M8 3h8v3h4a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4Zm2 3h4V5h-4Z"/><path d="M8 10h8v8H8Zm4 0v8M8 14h8" fill="none" stroke="white" stroke-width="1.5"/></svg>
<svg v-else-if="!category(r)&&r.order!.paymentMethod==='WECHAT'" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M19 10c0 4-4 7-9 7l-5 3 1-4C3 15 1 13 1 10c0-4 4-7 9-7s9 3 9 7Z"/><path d="M23 15c0 2-1 4-3 5l1 3-4-2c-4 0-7-2-7-6s3-6 7-6 6 3 6 6Z" stroke="#dffbf0" stroke-width="1.1"/><circle cx="6.5" cy="8.5" r="1" fill="white"/><circle cx="12.5" cy="8.5" r="1" fill="white"/></svg>
<svg v-else-if="!category(r)&&r.order!.paymentMethod==='ALIPAY'" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><rect x="2" y="2" width="20" height="20" rx="5"/><path d="M6 8h12M12 5v7M7 12h10c-2 5-6 7-11 6m2-5c3 2 7 4 12 5" fill="none" stroke="white" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>
<PromoterIcon v-else name="card"/>{{methodName(r)}}</span></td><td><span class="finance-pill" :class="r.order!.status==='PAID'?'green':['REJECTED','REFUNDED'].includes(r.order!.status||'')?'red':'orange'">{{state(r)}}</span></td><td v-if="!review">{{time(r.paidAt)}}</td><td><button type="button" class="finance-view" :class="{'finance-primary':review&&r.order!.status==='REVIEW_PENDING'}" @click="selected=r">{{review&&r.order!.status==='REVIEW_PENDING'?'审核':'查看'}}</button></td></tr></tbody></table><p v-if="!busy&&!error&&!rows.length" class="finance-empty">暂无记录</p></div>
<footer class="finance-pagination"><span>共 {{rows.length}} 条</span><div><button type="button" aria-label="上一页" :disabled="page<=1" @click="go(page-1)">‹</button><button v-for="n in pageNumbers" :key="n" type="button" :aria-current="page===n?'page':undefined" @click="go(n)">{{n}}</button><button type="button" aria-label="下一页" :disabled="page>=pages" @click="go(page+1)">›</button></div><select v-model.number="size" aria-label="每页条数" @change="go(1)"><option :value="10">10 条/页</option><option :value="20">20 条/页</option><option :value="50">50 条/页</option></select><label>跳至 <input v-model.number="jump" type="number" min="1" :max="pages" aria-label="跳转页码" @change="go(jump)"/> 页</label></footer></section>
<PaymentOrderDrawer v-if="selected" :key="selected.order!.orderId!" :record="selected" :user="user(selected)" :review="review" @close="selected=null" @changed="load"/>
</template><div v-else class="finance-empty"><h1>无权限</h1></div></section></template>
